function beautifulSplits(nums) {
  const n = nums.length;
  const lcp = Array.from({ length: n + 1 }, () => new Int32Array(n + 1));
  for (let i = n - 1; i >= 0; i--) {
    for (let j = i + 1; j < n; j++) {
      if (nums[i] === nums[j]) {
        lcp[i][j] = lcp[i + 1][j + 1] + 1;
      }
    }
  }
  let count = 0;
  for (let i = 1; i < n - 1; i++) {
    for (let j = i + 1; j < n; j++) {
      const firstIsPrefix = i <= j - i && lcp[0][i] >= i;
      const secondIsPrefix = j - i <= n - j && lcp[i][j] >= j - i;
      if (firstIsPrefix || secondIsPrefix) {
        count++;
      }
    }
  }
  return count;
}

