function beautifulSplits(nums) {
  // Try every pair of cut points and compare the parts element by element.
  const startsWith = (whole, part) => part.length <= whole.length && part.every((value, k) => whole[k] === value);
  let count = 0;
  for (let a = 1; a < nums.length; a++)
    for (let b = a + 1; b < nums.length; b++) {
      const first = nums.slice(0, a), second = nums.slice(a, b), third = nums.slice(b);
      if (startsWith(second, first) || startsWith(third, second)) count++;
    }
  return count;
}

