function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const n = size === 'large' ? int(1500, 2000) : int(1, 10);
  // Few distinct values make many matches; sometimes the whole range 0..50 is used.
  const top = rand() < 0.75 ? int(0, 2) : 50;
  // Half the arrays repeat a short pattern with a few random changes, which creates long common prefixes.
  const pattern = Array.from({ length: int(1, 4) }, () => int(0, top));
  const repeat = rand() < 0.5;
  const nums = Array.from({ length: n }, (_, k) => repeat && rand() < 0.9 ? pattern[k % pattern.length] : int(0, top));
  return [nums];
}
